INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 315,2,0,'Все правда, брат. Каждое слово. Ты сомневался?' FROM `creature_text` b WHERE b.`entry`=315 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY 'It\'s all true, brother. Every word. You doubted it?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 315,3,0,'Ты знаешь почему!' FROM `creature_text` b WHERE b.`entry`=315 AND b.`groupid`=3 AND b.`id`=0 AND BINARY b.`text`=BINARY 'You know why!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 315,5,0,'Разве ты сейчас этого не чувствуешь?' FROM `creature_text` b WHERE b.`entry`=315 AND b.`groupid`=5 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Aren\'t you feeling it right now?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 466,0,0,'Приветствую, гражданин.' FROM `creature_text` b WHERE b.`entry`=466 AND b.`groupid`=0 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Greetings citizen.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 946,0,0,'Легкая добыча.' FROM `creature_text` b WHERE b.`entry`=946 AND b.`groupid`=0 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Killing you be easy.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 946,0,1,'Ты скоро будешь совсем мертвый!' FROM `creature_text` b WHERE b.`entry`=946 AND b.`groupid`=0 AND b.`id`=1 AND BINARY b.`text`=BINARY 'You be dead soon!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 946,0,2,'Мое оружие хочет пить!' FROM `creature_text` b WHERE b.`entry`=946 AND b.`groupid`=0 AND b.`id`=2 AND BINARY b.`text`=BINARY 'My weapon be thirsty!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 946,0,3,'Я из тебя амулет сделаю!' FROM `creature_text` b WHERE b.`entry`=946 AND b.`groupid`=0 AND b.`id`=3 AND BINARY b.`text`=BINARY 'I gonna make you into mojo!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3692,2,0,'Хорошо, $N. Теперь я смогу добраться до Аубердина самостоятельно. Отправляйся к Терентису, он тебя ждет. Спасибо за помощь!' FROM `creature_text` b WHERE b.`entry`=3692 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY 'OK, $N. Now I can get to the Auberdine alone. Go to Terenthis, he\'s waiting for you. Thanks for the help!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3692,3,0,'Хорошо, удачи, друг. Спасибо за помощь.' FROM `creature_text` b WHERE b.`entry`=3692 AND b.`groupid`=3 AND b.`id`=0 AND BINARY b.`text`=BINARY 'OK, good luck friend. Thanks for the help.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3693,1,0,'Волкору нужна помощь?' FROM `creature_text` b WHERE b.`entry`=3693 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Volcor needs help?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3693,2,0,'Хорошо, я найду людей, которые ему помогут.' FROM `creature_text` b WHERE b.`entry`=3693 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY 'All right, I shall find people to help him.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3693,4,0,'Что происходит?' FROM `creature_text` b WHERE b.`entry`=3693 AND b.`groupid`=4 AND b.`id`=0 AND BINARY b.`text`=BINARY 'What is happening?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3693,5,0,'Волкору нужна помощь?' FROM `creature_text` b WHERE b.`entry`=3693 AND b.`groupid`=5 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Volcor needs help?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3693,6,0,'Ты знаешь, где он?' FROM `creature_text` b WHERE b.`entry`=3693 AND b.`groupid`=6 AND b.`id`=0 AND BINARY b.`text`=BINARY 'You know where he is?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 3693,7,0,'Хорошо. Я отправлю людей. Нужно найти его и помочь ему!' FROM `creature_text` b WHERE b.`entry`=3693 AND b.`groupid`=7 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Well, ok. I am sending people. We will need to find and help him!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 4854,1,0,'Умри, умри!' FROM `creature_text` b WHERE b.`entry`=4854 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Die, die!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 15341,6,0,'В атаку! Пусть они дорого за все заплатят!' FROM `creature_text` b WHERE b.`entry`=15341 AND b.`groupid`=6 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Attack and make them pay dearly!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 15341,7,0,'Сокрушите их! Выгоните их!' FROM `creature_text` b WHERE b.`entry`=15341 AND b.`groupid`=7 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Crush them! Drive them out!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 15341,8,0,'Не медлите! Уничтожьте их!' FROM `creature_text` b WHERE b.`entry`=15341 AND b.`groupid`=8 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Do not hesitate! Destroy them!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 22917,7,0,'Я чувствую твою ненависть.' FROM `creature_text` b WHERE b.`entry`=22917 AND b.`groupid`=7 AND b.`id`=0 AND BINARY b.`text`=BINARY 'I can feel your hatred.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 22917,7,1,'Поддайся своему страху!' FROM `creature_text` b WHERE b.`entry`=22917 AND b.`groupid`=7 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Give in to your fear!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 23197,0,1,'Пусть твоя кровь льется, как лилась моя!' FROM `creature_text` b WHERE b.`entry`=23197 AND b.`groupid`=0 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Bleed as I have bled!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 23197,0,2,'На этот раз ты в темницу не попадешь!' FROM `creature_text` b WHERE b.`entry`=23197 AND b.`groupid`=0 AND b.`id`=2 AND BINARY b.`text`=BINARY 'There shall be no prison for you this time!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 23197,0,3,'Тебе конец, демон!' FROM `creature_text` b WHERE b.`entry`=23197 AND b.`groupid`=0 AND b.`id`=3 AND BINARY b.`text`=BINARY 'Meet your end, demon!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 23574,1,1,'Хватит ныть!' FROM `creature_text` b WHERE b.`entry`=23574 AND b.`groupid`=1 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Stop your cryin\'!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 23574,5,0,'Ты только зря тратишь мое время!' FROM `creature_text` b WHERE b.`entry`=23574 AND b.`groupid`=5 AND b.`id`=0 AND BINARY b.`text`=BINARY 'All ya be doin\' is wastin\' ma time!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 23574,6,0,'Тебе не... убить... мой дух!' FROM `creature_text` b WHERE b.`entry`=23574 AND b.`groupid`=6 AND b.`id`=0 AND BINARY b.`text`=BINARY 'You can\'t... kill... me spirit!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 23863,2,1,'Многие еще падут, как ты!' FROM `creature_text` b WHERE b.`entry`=23863 AND b.`groupid`=2 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Lot more gonna fall like you!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 26648,4,0,'Мне очень любопытно, что произойдет, если ты проигнорируешь это и НЕ прыгнешь в воду.' FROM `creature_text` b WHERE b.`entry`=26648 AND b.`groupid`=4 AND b.`id`=0 AND BINARY b.`text`=BINARY 'I\'m rather curious as to what will happen, should you ignore this and NOT jump into the water.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 26693,6,0,'Спалите их до костей!' FROM `creature_text` b WHERE b.`entry`=26693 AND b.`groupid`=6 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Sear them to the bone!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 26693,6,1,'Вперед! Не оставляйте за собой ничего, кроме пепла!' FROM `creature_text` b WHERE b.`entry`=26693 AND b.`groupid`=6 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Go now! Leave nothing but ash in your wake!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 26693,6,2,'Очистите наши священные залы пламенем!' FROM `creature_text` b WHERE b.`entry`=26693 AND b.`groupid`=6 AND b.`id`=2 AND BINARY b.`text`=BINARY 'Cleanse our sacred halls with flame!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 28070,0,2,'Продолжайте! Тут каждому найдется кого прикончить!' FROM `creature_text` b WHERE b.`entry`=28070 AND b.`groupid`=0 AND b.`id`=2 AND BINARY b.`text`=BINARY 'Keep it up now. Plenty of death-dealing for everyone!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 28122,3,2,'Вот я, с мозгом размером с планету, а меня просят отвести тебя в соседнюю деревню. Это, по-вашему, удовольствие от работы? По-моему, нет.' FROM `creature_text` b WHERE b.`entry`=28122 AND b.`groupid`=3 AND b.`id`=2 AND BINARY b.`text`=BINARY 'Here I am, brain the size of a planet, and they ask me to take you to the other village. Call that job satisfaction? \'Cause I don\'t.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 28122,4,0,'Мохоброды были хорошим народом... они не заслужили этого.' FROM `creature_text` b WHERE b.`entry`=28122 AND b.`groupid`=4 AND b.`id`=0 AND BINARY b.`text`=BINARY 'The Mosswalkers were good people... they did not deserve this.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 28347,0,1,'Только в следующий раз добавляй вдвое меньше.' FROM `creature_text` b WHERE b.`entry`=28347 AND b.`groupid`=0 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Only put half as much in next time.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 28347,0,2,'Тогда в следующий раз добавляй вдвое больше!' FROM `creature_text` b WHERE b.`entry`=28347 AND b.`groupid`=0 AND b.`id`=2 AND BINARY b.`text`=BINARY 'Then put twice as much in next time!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 28355,0,1,'Сэр, наши покупатели жалуются, что в наших обезболивающих слишком много смерть-травы.' FROM `creature_text` b WHERE b.`entry`=28355 AND b.`groupid`=0 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Sir, our customers are complaining that there\'s too much Deathweed in our Anesthetics.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 28841,1,0,'Теперь я могу отдохнуть!' FROM `creature_text` b WHERE b.`entry`=28841 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Now I can have a rest!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 29120,5,0,'Когда-то, давным-давно, я был королем этой империи. При жизни я был ее защитником. После смерти я вернулся завоевателем. Теперь я снова защищаю королевство. Иронично, правда?' FROM `creature_text` b WHERE b.`entry`=29120 AND b.`groupid`=5 AND b.`id`=0 AND BINARY b.`text`=BINARY 'I was king of this empire once, long ago. In life I stood as champion. In death I returned as conqueror. Now I protect the kingdom once more. Ironic, yes? ' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 29183,80,0,'%s произносит мощное заклинание, убивая защитников и отбрасывая остальных.' FROM `creature_text` b WHERE b.`entry`=29183 AND b.`groupid`=80 AND b.`id`=0 AND BINARY b.`text`=BINARY '%s casts a powerful spell, killing the Defenders and knocking back the others.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 29227,73,0,'Появляется %s.' FROM `creature_text` b WHERE b.`entry`=29227 AND b.`groupid`=73 AND b.`id`=0 AND BINARY b.`text`=BINARY '%s arrives.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 29228,74,0,'%s становится тенью своего прошлого и подходит к отцу.' FROM `creature_text` b WHERE b.`entry`=29228 AND b.`groupid`=74 AND b.`id`=0 AND BINARY b.`text`=BINARY '%s becomes a shade of his past, and walks up to his father.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 30007,4,0,'Появляется Иггдрас!' FROM `creature_text` b WHERE b.`entry`=30007 AND b.`groupid`=4 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Yggdras emerges!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 30017,5,0,'Смрадобород идет за вами, малыши!' FROM `creature_text` b WHERE b.`entry`=30017 AND b.`groupid`=5 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Stinkbeard comin\' for you, little ones!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 30404,1,0,'Кошмар стал явью. Доктор Ужас уже здесь. Чтобы заставить тебя дрожать от страха. Чтобы поставить весь мир на колени. И я ничего... не почувствую.' FROM `creature_text` b WHERE b.`entry`=30404 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Now the nightmare\'s real.Now Dr. Terrible is here.To make you quake with fear.To make the whole world kneel.And I won\'t feel ...a thing' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 32865,0,1,'Я помню тебя... В горах... Но ты... что это? Где я--' FROM `creature_text` b WHERE b.`entry`=32865 AND b.`groupid`=0 AND b.`id`=1 AND BINARY b.`text`=BINARY 'I remember you... In the mountains... But you... what is this? Where am--' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 32865,14,0,'Теперь ваш черед, герои, отомстить за всех нас. Перед вами стоит нелегкая задача, но я помогу вам, чем смогу. Вы должны победить.' FROM `creature_text` b WHERE b.`entry`=32865 AND b.`groupid`=14 AND b.`id`=0 AND BINARY b.`text`=BINARY 'And now it falls to you, champions, to avenge us all. The task before you is great, but I will lend you my aid as I am able. You must prevail.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 33266,0,1,'Большое спасибо, $c!' FROM `creature_text` b WHERE b.`entry`=33266 AND b.`groupid`=0 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Many thanks, $c!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 33266,0,2,'За Орду!' FROM `creature_text` b WHERE b.`entry`=33266 AND b.`groupid`=0 AND b.`id`=2 AND BINARY b.`text`=BINARY 'For the Horde!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 34585,4,0,'А вместе с его возвращением пришли Алекстраза и Изера, чтобы наконец-то даровать Тельдрассилу свои благословения.' FROM `creature_text` b WHERE b.`entry`=34585 AND b.`groupid`=4 AND b.`id`=0 AND BINARY b.`text`=BINARY 'And with his return came Alexstrasza and Ysera, to at long last offer their blessings upon Teldrassil.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 35112,1,0,'Огонь!' FROM `creature_text` b WHERE b.`entry`=35112 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Fire!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 35112,1,1,'Держите баррикады! Не уступайте им ни пяди!' FROM `creature_text` b WHERE b.`entry`=35112 AND b.`groupid`=1 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Hold the barricades! Do not give them an inch!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 35112,1,2,'Не подпускайте их!' FROM `creature_text` b WHERE b.`entry`=35112 AND b.`groupid`=1 AND b.`id`=2 AND BINARY b.`text`=BINARY 'Keep them back!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 35124,0,0,'Брат!' FROM `creature_text` b WHERE b.`entry`=35124 AND b.`groupid`=0 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Brother!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 35124,1,0,'Скажи, что это неправда, брат. Скажи, что ты не умер убийцей!' FROM `creature_text` b WHERE b.`entry`=35124 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Tell me it\'s not true, brother. Tell me you didn\'t die a murderer!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 35124,2,0,'Но почему? Как ты только можешь?!' FROM `creature_text` b WHERE b.`entry`=35124 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY 'But why? How could you?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 35124,3,0,'Нет... НЕТ! ПРЕКРАТИ!' FROM `creature_text` b WHERE b.`entry`=35124 AND b.`groupid`=3 AND b.`id`=0 AND BINARY b.`text`=BINARY 'No... NO! STOP IT!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 38697,0,0,'Так точно, сэр! Немедленно, сэр!' FROM `creature_text` b WHERE b.`entry`=38697 AND b.`groupid`=0 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Aye aye sir! Immediately, sir!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 38826,0,0,'Ладненько, босс. Я это закончу.' FROM `creature_text` b WHERE b.`entry`=38826 AND b.`groupid`=0 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Oke doke, boss. I will finish this.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 38826,1,0,'Пора визжать, поросеночек!' FROM `creature_text` b WHERE b.`entry`=38826 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'It be time to squeal, little piggy!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 38871,1,0,'Интересно. Очень... интересно.' FROM `creature_text` b WHERE b.`entry`=38871 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Interesting. Very ... interesting.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 38873,0,0,'Держись, старина!' FROM `creature_text` b WHERE b.`entry`=38873 AND b.`groupid`=0 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Hang in there ol\' buddy!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 38876,0,0,'Прекрати стрелять, старый маразматик! Ты же так кого-нибудь убьешь!' FROM `creature_text` b WHERE b.`entry`=38876 AND b.`groupid`=0 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Stop shooting you senile idiot! You\'re going to kill somebody!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 38941,1,0,'А-а-ай — жжет! Давит! $GОн нас обманул:Она нас обманула;, убейте $Gего:ее;, убейте!' FROM `creature_text` b WHERE b.`entry`=38941 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'EeeKKeech - it stings! It crushes! $GHe:She; tricked us, kills $Ghim:her;, kill!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,0,5,'П-помогите мне' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=0 AND b.`id`=5 AND BINARY b.`text`=BINARY 'H-help me' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,1,0,'Спасибо, $r... До смерти было рукой подать. Можно мне немного побыть рядом с тобой?' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Thank you, $r... I was close to death. May I stay by your side for a moment?' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,1,1,'Моя жизнь спасена благодаря тебе, $c. Защищай меня еще немного, пока я восстанавливаю силы.' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=1 AND b.`id`=1 AND BINARY b.`text`=BINARY 'You\'ve saved my life, $c. Protect me for a few more moments while I recover.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,1,2,'За Вождя! Веди, я пойду за тобой.' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=1 AND b.`id`=2 AND BINARY b.`text`=BINARY 'For the Warchief You lead, I will follow.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,1,3,'Мне полагалось погибнуть в бою... что ж, в другой раз. Я пойду за тобой, пока не восстановлю силы.' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=1 AND b.`id`=3 AND BINARY b.`text`=BINARY 'I was supposed to die in battle... ah well, another day. I will follow you until I recover.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,2,0,'Еще раз спасибо. Теперь я вернусь в Колючий Холм.' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Thank you again. I will return to Razor Hill now.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,2,1,'Мне уже гораздо лучше. За Орду' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=2 AND b.`id`=1 AND BINARY b.`text`=BINARY 'I feel much better now. For the Horde' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39270,2,2,'Для меня было честью видеть тебя в бою, $n.' FROM `creature_text` b WHERE b.`entry`=39270 AND b.`groupid`=2 AND b.`id`=2 AND BINARY b.`text`=BINARY 'It was an honor to watch you fight, $n.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 39788,3,1,'Цель уничтожена.' FROM `creature_text` b WHERE b.`entry`=39788 AND b.`groupid`=3 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Target Annihilated.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 43950,5,0,'Теперь я вспоминаю... Все из-за тебя!' FROM `creature_text` b WHERE b.`entry`=43950 AND b.`groupid`=5 AND b.`id`=0 AND BINARY b.`text`=BINARY 'I remember now... it\'s all your fault!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52943,1,0,'Норкани все еще нужна твоя помощь!' FROM `creature_text` b WHERE b.`entry`=52943 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Norkani still be needin\' your help!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52943,2,0,'Наконец-то Норкани на свободе!' FROM `creature_text` b WHERE b.`entry`=52943 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY 'At last, Norkani is free!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52956,1,0,'Зеленый кулак империи троллей раздавит эту землю, и она снова станет нашей.' FROM `creature_text` b WHERE b.`entry`=52956 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'De green fist of de troll empire gonna crush dis land and make it our own again.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52956,2,0,'Это единственный путь, братья.' FROM `creature_text` b WHERE b.`entry`=52956 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY '\'Dis be de only way, bruddahs.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52958,1,0,'Эту землю у нас отняли, залив ее кровью.' FROM `creature_text` b WHERE b.`entry`=52958 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Dis land was taken from us in a tide of blood.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52962,1,0,'Это единственный путь, братья.' FROM `creature_text` b WHERE b.`entry`=52962 AND b.`groupid`=1 AND b.`id`=0 AND BINARY b.`text`=BINARY '\'Dis be de only way, bruddahs.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52962,2,0,'Зеленый кулак империи троллей раздавит эту землю, и она снова станет нашей.' FROM `creature_text` b WHERE b.`entry`=52962 AND b.`groupid`=2 AND b.`id`=0 AND BINARY b.`text`=BINARY 'De green fist of de troll empire gonna crush dis land and make it our own again.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52962,3,0,'Тролли Черного копья — глупцы. Никто не встанет на нашем пути.' FROM `creature_text` b WHERE b.`entry`=52962 AND b.`groupid`=3 AND b.`id`=0 AND BINARY b.`text`=BINARY 'De Darkspear be foolish.  No one gonna stand in our way.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52962,6,0,'Этот расколотый мир еще не перестал разваливаться, дружище.' FROM `creature_text` b WHERE b.`entry`=52962 AND b.`groupid`=6 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Dis shattered world not done breakin, mon.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52962,7,0,'Волны тьмы накроют все. Все тролли в опасности.' FROM `creature_text` b WHERE b.`entry`=52962 AND b.`groupid`=7 AND b.`id`=0 AND BINARY b.`text`=BINARY 'De tides of darkness gonna take over.  All da trolls be in danger.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 52962,8,0,'Тролли Черного копья — глупцы. Никто не встанет на нашем пути.' FROM `creature_text` b WHERE b.`entry`=52962 AND b.`groupid`=8 AND b.`id`=0 AND BINARY b.`text`=BINARY 'De Darkspear be foolish.  No one gonna stand in our way.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 55869,9,0,'Ненавижу вас всех.' FROM `creature_text` b WHERE b.`entry`=55869 AND b.`groupid`=9 AND b.`id`=0 AND BINARY b.`text`=BINARY 'I hate you all.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 55869,10,0,'Ненавижу милосердие.' FROM `creature_text` b WHERE b.`entry`=55869 AND b.`groupid`=10 AND b.`id`=0 AND BINARY b.`text`=BINARY 'I hate mercy.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 55869,11,0,'Моя ненависть пылает!' FROM `creature_text` b WHERE b.`entry`=55869 AND b.`groupid`=11 AND b.`id`=0 AND BINARY b.`text`=BINARY 'My hatred burns!' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 69473,5,1,'Забавно. Неужели победа и впрямь казалась тебе возможной?' FROM `creature_text` b WHERE b.`entry`=69473 AND b.`groupid`=5 AND b.`id`=1 AND BINARY b.`text`=BINARY 'Amusing. You really thought you could win.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 69473,5,2,'Прими неизбежное.' FROM `creature_text` b WHERE b.`entry`=69473 AND b.`groupid`=5 AND b.`id`=2 AND BINARY b.`text`=BINARY 'Accept the inevitable.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 69473,11,0,'Это лишь толика моей силы.' FROM `creature_text` b WHERE b.`entry`=69473 AND b.`groupid`=11 AND b.`id`=0 AND BINARY b.`text`=BINARY 'This is but a taste of my power.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) SELECT 69473,12,0,'Стойте! Я... Я вам не враг. Вы сильны, даже сильнее, чем он... возможно, вы правы. Возможно, надежда еще есть.\nНо под вами, смертными, зияет пропасть тьмы — огромная, бесконечная и всепоглощающая. Я не верю, что вы сможете свернуть с этого гибельного пути.\nНо... вы заслужили право попытаться. Прощайте.' FROM `creature_text` b WHERE b.`entry`=69473 AND b.`groupid`=12 AND b.`id`=0 AND BINARY b.`text`=BINARY 'Wait! I am... I am not your enemy. You are powerful, more powerful than he was, even... perhaps you are right. Perhaps there is still hope.\nBut there is a yawning chasm of darkness beneath you mortals, vast, endless, and all consuming. I do not believe that you can correct this doomed course.\nBut... you have earned the right to try. Farewell.' ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='',VALUES(`text_loc8`),`text_loc8`);
